        internal static string GetLabel(int modelHash, int seatIndex)
        {
            VehicleSeatLayoutRecord record = Get(modelHash);
            string label;
            return record != null
                && record.Labels.TryGetValue(seatIndex, out label)
                ? label : null;
        }

        internal static VehicleSeatLayoutRecord Get(int modelHash)
        {
            VehicleSeatLayoutRecord record;
            return All.TryGetValue(modelHash, out record) ? record : null;
        }
    }
